supercuts.co.uk.apply:
try {
	const field = document.querySelector('input#coupon_code, input#discount-code');
	field.dispatchEvent(new Event('input', { bubbles: true }));
	field.dispatchEvent(new Event('change'));
	document.querySelector('#discount-coupon-form button.apply, #discount-form .action-apply').click();
} catch(e) {}

